// План: specs/cards.md, тест 4.1. Тикет #c70f72 (עבר QA 17.11.2026). Менеджер 0500000004 (client), участник 0500000005 (provider).
// Две роли независимы, шаги в окне каждой. Только просмотр → @prod-safe.
import { test, expect } from '../../fixtures';
import { SHARED_WALLET_ID, MASK_DOTS_ONLY, waitMasks, expectNoFullCardNumber } from './helpers';

const MANAGEMENT = [/^הסרת /, /הוספת משתתפ/, /הזמנת משתתפ/, /ניהול משתתפ/];

test.describe('ארנק משותף — ביצוע תשלום', () => {
  test('«לשימוש בכרטיס» בארנק משותף: מנהל ומשתתף רואים «•••• •••• •••• NNNN»; למשתתף «טעינת כסף» ב«פעולות אחרונות» ואין ניהול משתתפים @prod-safe #c70f72', async ({ asUser }) => {
    const manager = await asUser('client');
    const member = await asUser('provider');
    const walletUrl = `/wallet/shared/${SHARED_WALLET_ID}`;

    // Менеджер: цифры + контроль, что элементы управления участниками существуют (позитивный контроль для проверки участника).
    await manager.goto(walletUrl);
    await expect(manager.getByRole('button', { name: 'לשימוש בכרטיס' })).toBeVisible({ timeout: 30_000 });
    const managesCount = await manager.getByRole('button', { name: MANAGEMENT[0] }).count();
    expect(managesCount, 'у менеджера должны быть кнопки удаления участников').toBeGreaterThan(0);
    await manager.getByRole('button', { name: 'לשימוש בכרטיס' }).click();
    await expect(manager.getByText('ביצוע תשלום').first()).toBeVisible({ timeout: 30_000 });
    const managerDigits = await waitMasks(manager, 1);
    expect(managerDigits).toHaveLength(1);
    await expect(manager.getByText(MASK_DOTS_ONLY)).toHaveCount(0);
    await expectNoFullCardNumber(manager);

    // Участник: тот же кошелёк.
    await member.goto(walletUrl);
    await expect(member.getByRole('button', { name: 'לשימוש בכרטיס' })).toBeVisible({ timeout: 30_000 });

    // «טעינת כסף» на вкладке «פעולות אחרונות»; управления участниками нет.
    await member.getByText('פעולות אחרונות', { exact: true }).first().click();
    await expect(member.getByText('טעינת כסף', { exact: true }).first()).toBeVisible();
    for (const re of MANAGEMENT) {
      await expect(member.getByRole('button', { name: re })).toHaveCount(0);
      await expect(member.getByText(re)).toHaveCount(0);
    }

    // «לשימוש בכרטיס» участника: те же 4 цифры, что у менеджера (один кошелёк).
    await member.getByRole('button', { name: 'לשימוש בכרטיס' }).click();
    await expect(member.getByText('ביצוע תשלום').first()).toBeVisible({ timeout: 30_000 });
    const memberDigits = await waitMasks(member, 1);
    expect(memberDigits).toEqual(managerDigits);
    await expect(member.getByText(MASK_DOTS_ONLY)).toHaveCount(0);
    await expectNoFullCardNumber(member);
  });
});
